from common import *
p=M([[1,0],[2,-1],[0,3]]);q=M([[1,1,-1],[2,0,3]]);r=M([[-1,1,-4],[-4,0,-6],[6,6,-6]]);b=M([[1,6],[3,1]])
x=S.symbols('x0:4');X=M(2,2,x);sol=S.solve(list(p*X*q-r),x);assert sol and p*X.subs(sol)*q==r
y=S.symbols('y0:6');Y=M(2,3,y);sy=list(S.linsolve(list(Y*p-b),y))[0];yy=Y.subs(dict(zip(y,sy)));assert yy*p==b
add('2.1',r'**a.** Đặt $X=\begin{bmatrix}a&b\\c&d\end{bmatrix}$. Từ hàng đầu của $PXQ=R$ có $a+2b=-1$, $a=1$, $-a+3b=-4$, nên $a=1,b=-1$. Các hàng còn lại xác định $c,d$, cho $$X='+tex(X.subs(sol))+r'.$$ Nhân lại $PXQ$ cho đúng $R$. **b.** Hệ $XP=S$ tách thành hai hàng: nếu một hàng của $X$ là $(u,v,w)$ và hàng tương ứng của $S$ là $(s,t)$, thì $u+2v=s$, $-v+3w=t$. Vì vậy đặt $w$ tự do rồi $v=3w-t$, $u=s-2v$. Toàn bộ nghiệm là $$X='+tex(yy)+r'.$$ Các ký hiệu còn tự do là tham số thực; nhân $XP$ kiểm tra.')
add('2.2',r'**a.** Đa thức có hệ số thực nên $p(U^T)=p(U)^T=\begin{bmatrix}1&-1\\3&0\end{bmatrix}$. **b.** Từ $U^3-5U^2+11U-4I=0$ suy ra $U(U^2-5U+11I)=4I$. Các đa thức của $U$ giao hoán với $U$, nên cũng có tích theo chiều ngược bằng $4I$. Do đó $U^{-1}=(U^2-5U+11I)/4$.')
add('2.3',r'Gọi $m$ là số phương trình, $n>m$ là số ẩn. Hạng $r\le m<n$, nên hệ thuần nhất $Av=0$ có ít nhất một ẩn tự do và có nghiệm $v\ne0$. Vì hệ đã cho tương thích, chọn một nghiệm $x_0$. Khi đó $A(x_0+tv)=b$ với mọi $t\in\mathbb R$; nếu $t\ne s$ thì $(t-s)v\ne0$. Vì vậy có vô hạn nghiệm phân biệt.')
add('2.4',r'**a.** $Ax_k=Ay+k(Ay-Az)=b+k(b-b)=b$. **b.** Nếu $x_k=x_m$ thì $(k-m)(y-z)=0$. Vì $y\ne z$, một thành phần của $y-z$ khác 0, buộc $k=m$. **c.** Mỗi số thực $k$ cho một nghiệm, và (b) bảo đảm các nghiệm khác nhau. Vì có vô hạn số thực, hệ có vô hạn nghiệm.')
add('2.5',r'**a.** Ma trận có dạng $A=\begin{bmatrix}0&a&b\\0&0&c\\0&0&0\end{bmatrix}$, nên $A^2=\begin{bmatrix}0&0&ac\\0&0&0\\0&0&0\end{bmatrix}$ và $A^3=0$. **b.** Với ma trận tam giác trên nghiêm ngặt cấp $n$, một số hạng trong $(A^k)_{ij}$ chỉ khác 0 khi có chuỗi chỉ số $i<i_1<\cdots<i_{k-1}<j$, suy ra $j-i\ge k$. Khi $k=n$ không cặp $i,j$ nào thỏa, vì $j-i\le n-1$. Do đó $A^n=0$.')
add('2.6',r'Dùng ký hiệu $I_{pq}=e_pe_q^T$. **a.** Tổng $\sum_i e_ie_i^T$ có đường chéo toàn 1, ngoài chéo bằng 0, nên bằng $I_n$. **b.** $I_{pq}I_{rs}=e_p(e_q^Te_r)e_s^T=\delta_{qr}I_{ps}$, cho hai trường hợp đề nêu. **c.** Tổng $\sum_{ij}a_{ij}I_{ij}$ có đúng ô $(i,j)$ là $a_{ij}$, nên bằng $A$. **d.** $I_{pq}AI_{rs}=e_p(e_q^TAe_r)e_s^T=a_{qr}I_{ps}$.')
add('2.7',r'**a.** $(aI)B=aB=B(aI)$ với mọi $B$. **b.** Giả sử $A$ giao hoán với mọi ma trận. Đặc biệt $AI_{jj}=I_{jj}A$. So sánh cột $j$ và hàng $j$ cho $a_{ij}=a_{ji}=0$ khi $i\ne j$, nên $A$ chéo. Tiếp theo $AI_{pq}=a_{pp}I_{pq}$, $I_{pq}A=a_{qq}I_{pq}$; giao hoán cho $a_{pp}=a_{qq}$ với mọi $p,q$. Vậy $A=aI$.')
add('2.8',r'Từ $M^2=0$ và sự giao hoán, có $A^2+BC=0$, $D^2+BC=0$, $B(A+D)=C(A+D)=0$. Đặt $S=A+D$. Khi đó $$S^3=(A^2+D^2+2AD)S=2(AD-BC)S.$$ Mặt khác $(A-D)^2=A^2+D^2-2AD=-2(AD+BC)$, nhưng cách trực tiếp hơn là $A^2S=-BCS=0$ và $D^2S=-BCS=0$. Do đó $AS^2=A(A+D)S=(A^2+AD)S=ADS$, và $S^3=2ADS$. Vì $A^2=D^2$, $ADS=AD(A+D)=A^2D+AD^2=-BCD-ABC=-BCS=0$. Vậy $S^3=0$.')
add('2.9',r'Điều kiện $A^{-1}=A^T$ tương đương hai hàng của $A$ là các vector đơn vị vuông góc. Hàng đầu $(a,b)$ thỏa $a^2+b^2=1$, nên viết được $(\cos\theta,\sin\theta)$. Vector đơn vị vuông góc với nó chỉ có hai lựa chọn $(-\sin\theta,\cos\theta)$ và $(\sin\theta,-\cos\theta)$, cho đúng hai dạng đề nêu. Chiều ngược: nhân mỗi ma trận với chuyển vị, dùng $\cos^2\theta+\sin^2\theta=1$, được $AA^T=A^TA=I$.')
add('2.10',r'**a.** Nhân trực tiếp $\begin{bmatrix}0&1\\1&0\end{bmatrix}^2=I_2$. **b.** Tích hai ma trận bằng 0 không kéo theo một thừa số bằng 0. Với ma trận ở (a), $A-I\ne0$ và $A+I\ne0$ nhưng $(A-I)(A+I)=A^2-I=0$. Sai lầm là áp dụng tính chất không có ước của 0 của số thực cho ma trận.')
add('2.11',r'Viết $E=I+aI_{pk}$, $F=I+bI_{qk}$. Vì $k\ne p,q$, công thức nhân đơn vị ma trận cho $I_{pk}I_{qk}=0=I_{qk}I_{pk}$. Do đó $$EF=I+aI_{pk}+bI_{qk}=FE.$$ Kết quả vẫn đúng nếu $p=q$: khi ấy hai phép cộng bội cùng một hàng nguồn vào cùng một hàng đích chỉ cộng các hệ số.')
add('2.12',r'Từ đối xứng viết $A=\begin{bmatrix}a&b\\b&d\end{bmatrix}$. Điều kiện $A^2=A$ cho $a^2+b^2=a$, $b(a+d)=b$, $d^2+b^2=d$. Nếu $b=0$, thì $a,d\in\{0,1\}$, được đúng bốn ma trận chéo đề liệt kê. Nếu $b\ne0$, chia phương trình giữa cho $b$ được $d=1-a$; hai phương trình còn lại cùng là $a^2+b^2=a$. Hoàn thành bình phương: $(a-1/2)^2+b^2=1/4$, suy ra $-1/2\le b\le1/2$. Ngược lại, thay các điều kiện này vào phép nhân cho ngay đối xứng và lũy đẳng.')
add('2.13',r'**(1) ⇒ (2).** Đặt $G=P^{-1}Q$, nên $Q=PG$ và $P+Q=P(I+G)$. Đẳng thức nghịch đảo trở thành $(I+G)^{-1}=I+G^{-1}$. Nhân với $G(I+G)$ (các đa thức của $G$ giao hoán), được $G=(I+G)^2$, tức $G^2+G+I=0$. **(2) ⇒ (1).** Từ $G(G+I)=-I$, có $G^{-1}=-(G+I)$ và $(I+G)^{-1}=-G$. Do đó $Q=PG$ và $P+Q=P(I+G)$ đều khả nghịch; $$P^{-1}+Q^{-1}=(I+G^{-1})P^{-1}=-GP^{-1}=(P+Q)^{-1}.$$')
